#include <iostream>
#include <string>
using namespace std;

struct Node {
    Node* children[26] = {};
    bool isEnd = false;
};

class Trie {
    Node* root;
public:
    Trie() { root = new Node(); }

    void insert(const string& word) {
        Node* cur = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!cur->children[idx]) cur->children[idx] = new Node();
            cur = cur->children[idx];
        }
        cur->isEnd = true;
    }

    bool search(const string& word) {
        Node* cur = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!cur->children[idx]) return false;
            cur = cur->children[idx];
        }
        return cur->isEnd;
    }

    bool startsWith(const string& prefix) {
        Node* cur = root;
        for (char c : prefix) {
            int idx = c - 'a';
            if (!cur->children[idx]) return false;
            cur = cur->children[idx];
        }
        return true;
    }
};

int main() {
    Trie trie;
    trie.insert("apple");
    trie.insert("app");
    trie.insert("apricot");
    cout << "search 'apple': " << trie.search("apple") << endl;
    cout << "search 'app': " << trie.search("app") << endl;
    cout << "search 'apt': " << trie.search("apt") << endl;
    cout << "startsWith 'ap': " << trie.startsWith("ap") << endl;
    cout << "startsWith 'apt': " << trie.startsWith("apt") << endl;
    return 0;
}
